def count_median_pairs():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:]))

    # Find the position of m in the array
    pos_m = -1
    for i in range(n):
        if a[i] == m:
            pos_m = i
            break

    if pos_m == -1:
        print(0)
        return

    # Count the number of elements greater than and less than m
    left_count = {0: 1}
    right_count = {0: 1}

    balance = 0
    for i in range(pos_m - 1, -1, -1):
        if a[i] < m:
            balance -= 1
        else:
            balance += 1
        if balance in left_count:
            left_count[balance] += 1
        else:
            left_count[balance] = 1

    balance = 0
    for i in range(pos_m + 1, n):
        if a[i] < m:
            balance -= 1
        else:
            balance += 1
        if balance in right_count:
            right_count[balance] += 1
        else:
            right_count[balance] = 1

    # Calculate the number of valid pairs
    result = 0
    for balance in left_count:
        if -balance in right_count:
            result += left_count[balance] * right_count[-balance]
        if 1 - balance in right_count:
            result += left_count[balance] * right_count[1 - balance]

    print(result)

