def count_median_pairs():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:]))

    # Find the position of m in the array
    pos_m = -1
    for i in range(n):
        if a[i] == m:
            pos_m = i
            break

    if pos_m == -1:
        print(0)
        return

    # Calculate prefix sums
    prefix = [0] * (n + 1)
    for i in range(n):
        if a[i] < m:
            prefix[i + 1] = prefix[i] - 1
        elif a[i] > m:
            prefix[i + 1] = prefix[i] + 1
        else:
            prefix[i + 1] = prefix[i]

    # Count the number of valid (l, r) pairs
    count = 0
    left_count = {}
    right_count = {}

    for i in range(pos_m + 1):
        left_count[prefix[i]] = left_count.get(prefix[i], 0) + 1

    for i in range(pos_m, n + 1):
        right_count[prefix[i]] = right_count.get(prefix[i], 0) + 1

    for key in left_count:
        if key in right_count:
            count += left_count[key] * right_count[key]

    print(count)

