def slide_and_merge_line(line):
    new_line = [num for num in line if num != 0]
    merged_line = []
    skip = False
    for i in range(len(new_line)):
        if skip:
            skip = False
            continue
        if i + 1 < len(new_line) and new_line[i] == new_line[i + 1]:
            merged_line.append(new_line[i] * 2)
            skip = True
        else:
            merged_line.append(new_line[i])
    return merged_line + [0] * (4 - len(merged_line))

def transpose(grid):
    return [list(row) for row in zip(*grid)]

def reverse(grid):
    return [list(reversed(row)) for row in grid]

def move_left(grid):
    return [slide_and_merge_line(row) for row in grid]

def move_right(grid):
    return reverse(move_left(reverse(grid)))

def move_up(grid):
    return transpose(move_left(transpose(grid)))

def move_down(grid):
    return transpose(move_right(transpose(grid)))

def main():
    import sys
    input = sys.stdin.read
    data = input().strip().split()
    grid = [list(map(int, data[i*4:(i+1)*4])) for i in range(4)]
    move = int(data[16])

