def self_explanatory_sentence():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    N = int(data[0])
    words = data[1:]

    num_to_word = {
        1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
        6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
        11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen",
        15: "fifteen", 16: "sixteen", 17: "seventeen", 18: "eighteen",
        19: "nineteen", 20: "twenty", 30: "thirty", 40: "forty",
        50: "fifty", 60: "sixty", 70: "seventy", 80: "eighty",
        90: "ninety"
    }

    def number_to_words(n):
        if n <= 20:
            return num_to_word[n]
        elif n < 100:
            tens, ones = divmod(n, 10)
            return num_to_word[tens * 10] + (num_to_word[ones] if ones else "")
        else:
            hundreds, remainder = divmod(n, 100)
            return num_to_word[hundreds] + "hundred" + (number_to_words(remainder) if remainder else "")

    def sentence_length_with_number(number_word):
        return sum(len(word) for word in words) - 1 + len(number_word)

    for number in range(1, 1000):
        number_word = number_to_words(number)
        if sentence_length_with_number(number_word) == number:
            words[words.index('$')] = number_word
            print(" ".join(words))
            break

