def max_min_fraction():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    canisters = list(map(int, data[1:]))

    canisters.sort()

    def is_possible(f):
        for i in range(n):
            if canisters[i] < (i + 1) * f:
                return False
        return True

    low, high = 0.0, 1.0
    result = 0.0

    for _ in range(100):
        mid = (low + high) / 2
        if is_possible(mid):
            result = mid
            low = mid
        else:
            high = mid

    if is_possible(result):
        print(f"{result:.9f}")
    else:
        print("impossible")

