def restore_circle():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    remembered = [(int(data[i * 2 + 1]), int(data[i * 2 + 2])) for i in range(n)]

    next_kid = {}
    for i in range(1, n + 1):
        a, b = remembered[i - 1]
        if a not in next_kid:
            next_kid[a] = []
        if b not in next_kid:
            next_kid[b] = []
        next_kid[a].append(b)
        next_kid[b].append(a)

    p = [1]
    current = 1
    visited = {1}

    while len(p) < n:
        for kid in next_kid[current]:
            if kid not in visited:
                p.append(kid)
                visited.add(kid)
                current = kid
                break

    print(' '.join(map(str, p)))

