import math

def count_elegant_numbers(n):
    if n < 2:
        return 0
    # Sieve of Eratosthenes to find all primes up to sqrt(n)
    limit = int(math.sqrt(n)) + 1
    is_prime = [True] * (limit + 1)
    primes = []
    for i in range(2, limit + 1):
        if is_prime[i]:
            primes.append(i)
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False

    # Inclusion-Exclusion principle to count non-elegant numbers
    def count_non_elegant(n, primes):
        m = len(primes)
        count = 0
        for mask in range(1, 1 << m):
            product = 1
            bits = 0
            for i in range(m):
                if mask & (1 << i):
                    product *= primes[i]
                    bits += 1
                    if product > n:
