def xenia_weights():
    import sys
    input = sys.stdin.read
    data = input().split()

    available_weights = data[0]
    m = int(data[1])

    weights = [i + 1 for i in range(10) if available_weights[i] == '1']

    if not weights:
        print("NO")
        return

    left, right = 0, 0
    result = []

    def can_place(weight, left, right, turn):
        if turn % 2 == 0:
            return left + weight > right
        else:
            return right + weight > left

    def backtrack(turn):
        if len(result) == m:
            return True
        for weight in weights:
            if (not result or result[-1] != weight) and can_place(weight, left, right, turn):
                result.append(weight)
                if turn % 2 == 0:
                    left += weight
                else:
                    right += weight
                if backtrack(turn + 1):
                    return True
                result.pop()
                if turn % 2 == 0:
                    left -= weight
                else:
                    right -= weight
        return False

    if backtrack(0):
        print("YES")
        print(" ".join(map(str, result)))
    else:
        print("NO")
