    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    y = list(map(int, data[1:]))

    if n == 3:
        print("Yes")
        return

    def check_line(exclude_index):
        x1, y1 = 1, y[0] if exclude_index != 0 else y[1]
        x2, y2 = 2, y[1] if exclude_index != 1 else y[2]
        dx, dy = x2 - x1, y2 - y1

        line_points = set()
        for i in range(n):
            if i == exclude_index:
                continue
            xi, yi = i + 1, y[i]
            if (xi - x1) * dy == (yi - y1) * dx:
                line_points.add(i)

        if len(line_points) == n - 1:
            return True

        remaining_points = set(range(n)) - line_points - {exclude_index}
        if len(remaining_points) <= 1:
            return True

        x1, y1 = next(iter(remaining_points)) + 1, y[next(iter(remaining_points))]
        x2, y2 = next(iter(remaining_points - {next(iter(remaining_points))})) + 1, y[next(iter(remaining_points - {next(iter(remaining_points))}))]
        dx, dy = x2 - x1, y2 - y1

        for i in remaining_points:
            xi, yi = i + 1, y[i]
            if (xi - x1) * dy != (yi - y1) * dx:
                return False

        return True

    if check_line(0) or check_line(1) or check_line(2):
        print("Yes")
    else:
        print("No")

