    results = []

    for case in range(t):
        n = int(data[case + 1])

        if n == 1:
            results.append("-1")
            continue

        # Find the minimum number of nights
        nights = 0
        current_mass = 1
        split_plan = []

        while current_mass < n:
            nights += 1
            split_plan.append(0)
            if current_mass * 2 <= n:
                current_mass *= 2
                split_plan[-1] = current_mass // 2
            else:
                break

        if current_mass == n:
            results.append(f"{nights}")
            results.append(" ".join(map(str, split_plan)))
        else:
            # Try to adjust the last day to reach exactly n
            while current_mass < n:
                nights += 1
                split_plan.append(0)
                if current_mass * 2 <= n:
                    current_mass *= 2
                    split_plan[-1] = current_mass // 2
                else:
                    break

            if current_mass == n:
                results.append(f"{nights}")
                results.append(" ".join(map(str, split_plan)))
            else:
                results.append("-1")

