def find_min_groups(n, array):
    from collections import defaultdict
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    array = list(map(int, data[1:n+1]))

    def prime_factors(x):
        factors = defaultdict(int)
        if x < 0:
            x = -x
        d = 2
        while d * d <= x:
            while (x % d) == 0:
                factors[d] += 1
                x //= d
            d += 1
        if x > 1:
            factors[x] += 1
        return factors

    def normalize_factors(factors):
        return tuple((p, e % 2) for p, e in sorted(factors.items()) if e % 2 != 0)

    def min_groups(subarray):
        factor_count = defaultdict(int)
        for num in subarray:
            factors = prime_factors(num)
            norm_factors = normalize_factors(factors)
            factor_count[norm_factors] += 1
        return len(factor_count)

    result = [0] * n
    for start in range(n):
        for end in range(start, n):
