    degree = n
    while not is_prime(degree):
        degree += 1

    # Calculate the number of edges
    m = (degree * n) // 2
    if not is_prime(m):
        return -1

    # Generate the edges
    edges = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if len(edges) < m:
                edges.append((i, j))
            else:
                break
        if len(edges) >= m:
            break

    return m, edges

