def count_perfectly_balanced_striped_bsts(n):
    MOD = 998244353

    if n % 2 == 1:
        return 0

    def factorial_mod(x, mod):
        result = 1
        for i in range(2, x + 1):
            result = (result * i) % mod
        return result

    def mod_inv(x, mod):
        return pow(x, mod - 2, mod)

    def binomial_mod(n, k, mod):
        if k > n:
            return 0
        num = factorial_mod(n, mod)
        denom = (factorial_mod(k, mod) * factorial_mod(n - k, mod)) % mod
        return (num * mod_inv(denom, mod)) % mod

    half_n = n // 2
    result = binomial_mod(n, half_n, MOD)
    return result

