def count_group_variants():
    import sys
    input = sys.stdin.read
    n = int(input().strip())
    result = 0
    for i in range(5, 8):
        if n >= i:
            result += comb(n, i)
    print(result)

def comb(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    c = 1
    for i in range(k):
        c = c * (n - i) // (i + 1)
    return c
