    data = input().split()

    n = int(data[0])
    m = int(data[1])
    p = int(data[2])

    board = []
    index = 3
    for _ in range(n):
        board.append([int(data[index + j]) for j in range(m)])
        index += m

    def is_winning(board):
        return all(all(cell == p for cell in row) for row in board)

    def apply_move(board, r, c):
        for i in range(n):
            board[i][c] = (board[i][c] % p) + 1
        for j in range(m):
            if j != c:
                board[r][j] = (board[r][j] % p) + 1

    def find_solution():
        from collections import deque

        initial_state = tuple(tuple(row) for row in board)
        queue = deque([(initial_state, [])])
        visited = set()
        visited.add(initial_state)

        while queue:
            current_board, moves = queue.popleft()

            if is_winning(current_board):
                return moves

            for r in range(n):
                for c in range(m):
                    new_board = [list(row) for row in current_board]
                    apply_move(new_board, r, c)
                    new_state = tuple(tuple(row) for row in new_board)

                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, moves + [r * m + c + 1]))

        return None

    solution = find_solution()

    if solution is None:
        print(-1)
    else:
        print(len(solution))
        print(' '.join(map(str, solution)))

