def solve_bar_code():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    n = int(data[0])
    row_specs = [list(map(int, line.split())) for line in data[1:n+1]]
    col_specs = [list(map(int, line.split())) for line in data[n+1:2*n+1]]

    def fill_line(spec, length):
        line = ['0'] * length
        index = 0
        for group in spec:
            if index + group > length:
                return None
            for i in range(group):
                line[index + i] = '1'
            index += group + 1
        return line

    def is_valid(grid, row_specs, col_specs):
        for i, spec in enumerate(row_specs):
            line = ''.join(grid[i])
            groups = [len(g) for g in line.split('0') if g]
            if groups != spec:
                return False
        for j, spec in enumerate(col_specs):
            line = ''.join(grid[i][j] for i in range(n))
            groups = [len(g) for g in line.split('0') if g]
            if groups != spec:
                return False
        return True

    def backtrack(grid, row):
        if row == n:
            if is_valid(grid, row_specs, col_specs):
                return grid
            return None

        for spec in row_specs[row]:
            line = fill_line(spec, n + 1)
            if line is not None:
                grid[row] = line
                result = backtrack(grid, row + 1)
                if result is not None:
                    return result
        return None

    grid = [['0'] * (n + 1) for _ in range(n)]
    solution = backtrack(grid, 0)

    if solution:
        for row in solution:
            print(''.join(row))
        for j in range(n + 1):
            print(''.join(solution[i][j] for i in range(n)))
