def election_outcome():
    import sys
    input = sys.stdin.read
    data = input().split()

    n, k, m, a = map(int, data[:4])
    votes = list(map(int, data[4:4+a]))

    vote_count = [0] * n
    last_vote_time = [-1] * n

    for i, v in enumerate(votes):
        vote_count[v-1] += 1
        last_vote_time[v-1] = i

    results = [3] * n

    for i in range(n):
        if vote_count[i] == 0:
            continue

        # Check if candidate i is guaranteed to win
        potential_votes = vote_count[i] + (m - a)
        rank = 1
        for j in range(n):
            if i != j:
                if vote_count[j] > potential_votes or (vote_count[j] == potential_votes and last_vote_time[j] < last_vote_time[i]):
