    input = sys.stdin.read
    from collections import deque

    data = input().strip().split()
    P, R, L = int(data[0]), int(data[1]), int(data[2])
    edges = [(int(data[i]), int(data[i+1])) for i in range(3, len(data), 2)]

    # Create adjacency list for the graph
    graph = {i: [] for i in range(-2, R)}
    for e1, e2 in edges:
        graph[e1].append(e2)
        graph[e2].append(e1)

    # BFS to find the shortest path from -2 to -1
    def bfs():
        queue = deque([(-2, 0)])
        visited = set([-2])
        while queue:
            node, dist = queue.popleft()
            if node == -1:
                return dist
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))
        return float('inf')

    # Find the shortest path length
