def river_crossing():
    import sys
    from collections import deque

    input = sys.stdin.read
    data = input().split()

    P = int(data[0])
    R = int(data[1])
    L = int(data[2])

    edges = []
    index = 3
    for _ in range(L):
        E1 = int(data[index])
        E2 = int(data[index + 1])
        edges.append((E1, E2))
        index += 2

    # Create adjacency list
    graph = {}
    for E1, E2 in edges:
        if E1 not in graph:
            graph[E1] = []
        if E2 not in graph:
            graph[E2] = []
        graph[E1].append(E2)
        graph[E2].append(E1)

    # BFS to find the shortest path from -2 to -1
    def bfs():
        queue = deque([(-2, 0)])
        visited = set([-2])
        while queue:
            node, dist = queue.popleft()
            if node == -1:
                return dist
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))
        return float('inf')

    # Find the shortest path for one person
    shortest_path = bfs()

    if shortest_path == float('inf'):
        print(f"{P} people left behind")
    else:
        if shortest_path * P <= L:
            print(shortest_path * P)
        else:
            # Calculate how many people can cross
            max_people = L // shortest_path
            people_left_behind = P - max_people
            print(f"{people_left_behind} people left behind")

