    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = list(map(int, data[1:n+1]))

    from collections import defaultdict
    import heapq

    def lowest_prime_divisor(x):
        if x % 2 == 0:
            return 2
        for i in range(3, int(x**0.5) + 1, 2):
            if x % i == 0:
                return i
        return x

    def factorial(x):
        if x == 0 or x == 1:
            return 1
        result = 1
        for i in range(2, x + 1):
            result *= i
        return result

    nodes = [factorial(ki) for ki in k]

    max_node = max(nodes)

    dist = defaultdict(lambda: float('inf'))
    dist[1] = 0

    pq = [(0, 1)]

    while pq:
        current_dist, node = heapq.heappop(pq)

        if current_dist > dist[node]:
            continue

        if node > 1:
            next_node = node // lowest_prime_divisor(node)
            if current_dist + 1 < dist[next_node]:
                dist[next_node] = current_dist + 1
                heapq.heappush(pq, (dist[next_node], next_node))

    total_distance = sum(dist[node] for node in nodes)

