    def is_cool(submatrix):
        r = len(submatrix)
        s = len(submatrix[0])
        if r > 1 and s > 1:
            return submatrix[0][0] + submatrix[r-1][s-1] <= submatrix[0][s-1] + submatrix[r-1][0]
        return True

    def is_extremely_cool(r1, c1, r2, c2):
        for i in range(r1, r2):
            for j in range(c1, c2):
                if not is_cool([row[j:c2] for row in matrix[i:r2]]):
                    return False
        return True

